------------ import ------------
local KTool = CS.Engine.Lib.KTool
local UIEventProxy = CS.Engine.UI.UIEventProxy
local UIModule = CS.Engine.UI.UIModule
------------ import ------------

------------ define ------------
local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")
------------ define ------------

---@class CatHouseTechnologyNode
---@field Text                          	UnityEngine.UI.Text @显示文本
---@field typeSwitch                    	Game.Native.Common.UISwitchText @状态
---@field ImgIcon                       	Engine.UI.RawImageAlterable @合卡技icon
local CatHouseTechnologyNode = Class('CatHouseTechnologyNode')

function CatHouseTechnologyNode:__init()
    self.pVo = nil
    self.container = nil
end

function CatHouseTechnologyNode:__delete()
    self.vo = nil
    self.container = nil
end

function CatHouseTechnologyNode:Awake()
    self.container = self.typeSwitch.transform.parent:Find("LableLayout")
    self.prefabGo = self.Text.transform.parent.gameObject
    local BtnTechnologyGroup = self.controller.transform:Find("BtnTechnologyGroup")
    UIEventProxy.Create(BtnTechnologyGroup.gameObject).onPointerClick = function()
        ---@type UnitSkillVo
        local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(table.takeFirst(self.pVo.skillIdList))
        local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(vo.skillId, 1)
        UIModule.OpenDialog({ id = Constants.UITypeIds.CatHouseHandbookTechnologyTipDialog, parameters = {
            unitVo = vo, skillVo = skillVo
        } })
    end
end

---FreshUI
---@param vo CatHouseCatDataVo
function CatHouseTechnologyNode:FreshUI(vo, isUnlocked)
    self.pVo = vo
    ---@type UnitSkillVo
    local vo = QuestConfMgr:GetInstance():GetMergeSkillVo(table.takeFirst(vo.skillIdList))
    local skillVo = UIBattlingTools.GetSkillCardInfoBySkillId(vo.skillId, 1)
    CfUtils.FillText(self.typeSwitch, skillVo.skillName)
    local status = 1
    if not isUnlocked then
        status = 2
    end
    CfUtils.FillImage(self.ImgIcon, vo.photo2Path)
    CfUtils.SetUISwitchText(self.typeSwitch,  status)
    KTool.SetActive(self.prefabGo, false)
    self:FillTag(vo)
end

---FillTag
---@param vo UnitSkillVo
function CatHouseTechnologyNode:FillTag(vo)
    local t = {}
    if vo.typeOne ~= "" then
        table.insert(t, {
            name = vo.typeOne,
            status = vo.typeOneColor,
        })
    end

    if vo.typeTwo ~= "" then
        table.insert(t, {
            name = vo.typeTwo,
            status = vo.typeTwoColor,
        })
    end

    for k, v in pairs(t) do
        local go = self.container.transform:Find("cell"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.prefabGo, self.container.gameObject)
            go.name = "cell"..k
        end
        CfUtils.FillText(go.transform:Find("Text"), v.name)
        CfUtils.SetUISwitchImage(go, v.status)
        KTool.SetActive(go, true)
    end
end

function CatHouseTechnologyNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CatHouseTechnologyNode